GUARD = (
    re.compile("本批"),
    re.compile(r"核验日[期]?[：:]?\s*\*{0,2}20\d\d"),
    re.compile(r"大纲 S\d\d"),
    re.compile(r"旧第 \d+ 章"),
    re.compile("扩展计划"),
    re.compile(r"Python 3\.\d+\.\d+"),
    re.compile(r"2\.14\.1\+cpu"),
    re.compile(r"2026-10-(?:18|19|20|30)"),
    re.compile(r"\*\*S\d\d：\*\*"),
    re.compile("沿用大纲"),
)
REMOVED = {"08j_training_frameworks.md": ['本次验证为节省重复安装空间，使用独立 /tmp/zero2llm-p20-venv，并只读复用原环境的 Torch / Tokenizers 路径；新增包写入独立环境，核对原环境版本未变。上面的干净环境命令是读者的安装路线，不要求复刻这个路径优化。']}
KEPT_LOCKS = [("08o_qwen3_case.md", "Jinja2 `3.1.6`")]
H_HEADING = "## 附录 H：版本与来源 {#p28.h-版本与来源}"


def outside_fences(text):
    kept, fence = [], False
    for line in text.split("\n"):
        if line.startswith("```"):
            fence = not fence
            kept.append("")
            continue
        kept.append("" if fence else line)
    return "\n".join(kept)


def outside_appendix_h(text):
    at = text.find(H_HEADING)
    return text if at < 0 else text[:at]


class B7MetaInfoTest(unittest.TestCase):
    def test_changed_sentences(self):
        for name, pairs in CHANGED.items():
            body = (CHAPTERS / name).read_text(encoding="utf-8")
            for old, new in pairs:
                with self.subTest(file=name, old=old[:24]):
                    self.assertEqual(body.count(old), 0)
                    self.assertEqual(body.count(new), 1)

    def test_kept_sentences(self):
        for name, sentences in KEPT.items():
            body = (CHAPTERS / name).read_text(encoding="utf-8")
            for sentence in sentences:
                with self.subTest(file=name, sentence=sentence[:24]):
                    self.assertEqual(body.count(sentence), 1)

    def test_removed_sentences(self):
        for name, sentences in REMOVED.items():
            body = (CHAPTERS / name).read_text(encoding="utf-8")
            for sentence in sentences:
                with self.subTest(file=name, sentence=sentence[:24]):
                    self.assertEqual(body.count(sentence), 0)
                    self.assertNotIn("zero2llm-p20-venv", body)

    def test_kept_version_locks(self):
        for name, fragment in KEPT_LOCKS:
            with self.subTest(file=name, fragment=fragment):
                self.assertEqual((CHAPTERS / name).read_text(encoding="utf-8").count(fragment), 1)

    def test_appendix_h_rows(self):
        body = (CHAPTERS / "10_appendix.md").read_text(encoding="utf-8")
        self.assertLess(body.index("## 附录 G："), body.index(H_HEADING))
        section = body.split(H_HEADING, 1)[1]
        parsed = []
        for line in section.splitlines():
            if not line.startswith("|"):
                continue
            if re.match(r"^\|\s*---", line):
                continue
            parsed.append(line)
        self.assertEqual(parsed[0], "| 章 | 内容 | 版本 / 日期 |")
        data = parsed[1:]
        self.assertEqual(len(data), len(APPENDIX_ROWS))
        self.assertEqual(data, APPENDIX_ROWS)
        for row in APPENDIX_ROWS:
            with self.subTest(row=row):
                self.assertEqual(section.count(row), 1)

    def test_guard_outside_fences_and_appendix_h(self):
        allow = {name: sentences for name, sentences in KEPT.items()}
        for path in sorted(CHAPTERS.glob("*.md")):
            text = outside_appendix_h(outside_fences(path.read_text(encoding="utf-8")))
            for pattern in GUARD:
                for match in pattern.finditer(text):
                    ok = False
                    for sentence in allow.get(path.name, []):
                        start = 0
                        while True:
                            at = text.find(sentence, start)
                            if at < 0:
                                break
                            if at <= match.start() < at + len(sentence):
                                ok = True
                                break
                            start = at + 1
                        if ok:
                            break
                    with self.subTest(file=path.name, pattern=pattern.pattern, hit=match.group()):
                        self.assertTrue(ok, match.group())


